"use client"

import { useId, useRef } from "react"
import { useIsomorphicLayoutEffect } from "../lib/hooks/use-isomorphic-layout-effect"
import { usePointerVars } from "../lib/hooks/use-pointer-vars"
import { svgId } from "../aurora/internal/backdrop"
import { DotPatternSvg } from "./dot-pattern-svg"

interface DotPatternGlowProps {
  gap: number
  radius: number
}

/**
 * The bright copy of the dots, revealed by a radial mask at the pointer. The pattern itself is
 * inert, so the pointer is tracked on the element the pattern fills (or on the pattern when it
 * wraps content) and its CSS variables cascade down into the mask.
 */
export const DotPatternGlow = ({ gap, radius }: DotPatternGlowProps) => {
  const ref = useRef<HTMLDivElement>(null)
  const target = useRef<HTMLElement | null>(null)
  const id = svgId("kg-dots-glow", useId())

  useIsomorphicLayoutEffect(() => {
    const root = ref.current?.closest<HTMLElement>(".kg-dot-pattern")
    target.current = root?.hasAttribute("data-wrapper")
      ? root
      : (root?.parentElement ?? null)
  }, [])

  usePointerVars(target, {
    onMove: () => {
      if (ref.current) ref.current.dataset.active = ""
    },
    onLeave: () => {
      if (ref.current) delete ref.current.dataset.active
    },
  })

  return (
    <div
      ref={ref}
      className="kg-dot-pattern__glow absolute inset-0 text-[var(--_glow)] opacity-0 transition-opacity duration-[var(--kg-duration-slower)] ease-kg-out data-active:opacity-100"
    >
      <DotPatternSvg
        id={id}
        gap={gap}
        radius={Math.min(radius * 1.6, gap / 2)}
        className="kg-dot-pattern__svg absolute inset-0 block"
      />
    </div>
  )
}

/* Edge masks and the pointer-following glow are gradient stacks: neither fits in utilities. */
@layer kg.components {
  .kg-dot-pattern {
    &[data-mask="radial"] > .kg-dot-pattern__layer {
      mask-image: radial-gradient(ellipse 70% 70% at 50% 50%, #000 20%, transparent 100%);
    }

    &[data-mask="top"] > .kg-dot-pattern__layer {
      mask-image: radial-gradient(ellipse 90% 80% at 50% 0%, #000 25%, transparent 100%);
    }

    &[data-mask="bottom"] > .kg-dot-pattern__layer {
      mask-image: radial-gradient(ellipse 90% 80% at 50% 100%, #000 25%, transparent 100%);
    }

    &[data-mask="edges"] > .kg-dot-pattern__layer {
      mask-image:
        linear-gradient(to right, transparent, #000 15% 85%, transparent),
        linear-gradient(to bottom, transparent, #000 15% 85%, transparent);
      mask-composite: intersect;
    }
  }

  /* --kg-pointer-x/y are written by usePointerVars on the tracked element and inherited here. */
  .kg-dot-pattern__glow {
    --_at: var(--kg-pointer-x, -100vmax) var(--kg-pointer-y, -100vmax);

    background: radial-gradient(
      circle var(--_glow-radius) at var(--_at),
      color-mix(in oklab, var(--_glow) 12%, transparent),
      transparent 80%
    );
    mask-image: radial-gradient(circle var(--_glow-radius) at var(--_at), #000 25%, transparent);
  }
}

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  useId,
} from "react"
import {
  type BackdropMask,
  backdropRoot,
  hasChildren,
  svgId,
} from "../aurora/internal/backdrop"
import { DotPatternGlow } from "./dot-pattern-glow"
import { DotPatternSvg } from "./dot-pattern-svg"

export type DotPatternMask = BackdropMask

export interface DotPatternProps extends HTMLAttributes<HTMLDivElement> {
  /** Distance between dot centres, in px. */
  gap?: number
  /** Dot radius, in px. */
  radius?: number
  /** Any CSS color. Defaults to the foreground at low alpha. */
  color?: string
  /** Dots near the pointer brighten. Tracks the parent element, or this one when it wraps content. */
  glow?: boolean
  /** Any CSS color for lit dots. Defaults to the ink. */
  glowColor?: string
  /** Radius of the lit area, in px. */
  glowRadius?: number
  /** Fade the dots out toward the edges. */
  mask?: DotPatternMask
  /** Optional content, painted above the dots. */
  children?: ReactNode
}

/**
 * An SVG dot grid. Static by default and server-component safe; `glow` mounts a small client part
 * that lights the dots around the pointer through CSS variables, without re-rendering.
 */
export const DotPattern = forwardRef<HTMLDivElement, DotPatternProps>(
  (
    {
      gap = 20,
      radius = 1,
      color,
      glow = false,
      glowColor,
      glowRadius = 180,
      mask = "radial",
      className,
      style,
      children,
      ...props
    },
    ref,
  ) => {
    const wrapper = hasChildren(children)
    const id = svgId("kg-dots", useId())
    const spacing = Math.max(gap, 2)
    const dot = Math.min(Math.max(radius, 0.1), spacing / 2)

    return (
      <div
        ref={ref}
        {...backdropRoot(
          "kg-dot-pattern absolute inset-0 overflow-hidden pointer-events-none data-wrapper:relative data-wrapper:inset-auto data-wrapper:overflow-visible data-wrapper:isolate data-wrapper:pointer-events-auto [--_glow:var(--kg-dot-glow-color,var(--kg-ink))] [--_glow-radius:var(--kg-dot-glow-radius,180px)]",
          className,
          wrapper,
        )}
        data-mask={mask}
        style={
          {
            ...(color ? { "--kg-dot-color": color } : null),
            ...(glowColor ? { "--kg-dot-glow-color": glowColor } : null),
            "--kg-dot-glow-radius": `${Math.max(glowRadius, 0)}px`,
            ...style,
          } as CSSProperties
        }
        {...props}
      >
        <div
          className="kg-dot-pattern__layer pointer-events-none absolute inset-0 z-0 overflow-hidden text-[var(--kg-dot-color,color-mix(in_oklab,var(--kg-fg)_30%,transparent))]"
          aria-hidden="true"
        >
          <DotPatternSvg
            id={id}
            gap={spacing}
            radius={dot}
            className="kg-dot-pattern__svg absolute inset-0 block"
          />
          {glow && <DotPatternGlow gap={spacing} radius={dot} />}
        </div>
        {wrapper && <div className="kg-dot-pattern__content relative z-1">{children}</div>}
      </div>
    )
  },
)

DotPattern.displayName = "DotPattern"
